export function openapi(){
 const api={openapi:'3.1.1',info:{title:'Independent Real Estate SaaS API — Design Contract',version:'1.0.0',description:'Proposed contract only. No application endpoints have been deployed. Provider webhooks use their own documented raw payload/signature adapters; the normalized envelope is internal.'},servers:[{url:'https://api.platform.example',description:'Reserved example host; not a live service'}],tags:[...new Set(operations.map(o=>o.module))].map(name=>({name})),security:[{Session:[]}],paths:{},components:{securitySchemes:{Session:{type:'apiKey',in:'cookie',name:'__Host-platform_session',description:'Verified BFF session. Mutations also require CSRF token + Origin verification.'},VisitorSession:{type:'apiKey',in:'cookie',name:'visitor_session',description:'Short-lived site-bound HttpOnly visitor session; no organization administration privileges.'},ProviderSignature:{type:'apiKey',in:'header',name:'X-Provider-Signature',description:'Placeholder normalized security scheme. Actual header and signature algorithm are provider-specific and require exact raw-body validation.'}},schemas:S}};
 for(const o of operations){const params=[];for(const m of o.url.matchAll(/\{([^}]+)\}/g))params.push({name:m[1],in:'path',required:true,schema:m[1]==='provider'?str(80):uuid});if(o.page)params.push({name:'cursor',in:'query',schema:str(4096)},{name:'limit',in:'query',schema:{type:'integer',minimum:1,maximum:100,default:25}});if(o.listingSearch)params.push({name:'filter',in:'query',content:{'application/json':{schema:ref('ListingCriteria')}}},{name:'sort',in:'query',schema:en('updated_desc','price_asc','price_desc')});if(o.module==='CRM'&&o.method==='get'&&o.page)params.push({name:'filter',in:'query',content:{'application/json':{schema:ref('LeadFilter')}}});if(o.method!=='get'&&!o.webhook){params.push({name:'Idempotency-Key',in:'header',required:true,schema:str(100)});if(!o.public&&!o.visitor)params.push({name:'X-CSRF-Token',in:'header',required:true,schema:str(4096)});}if(['patch','put'].includes(o.method))params.push({name:'If-Match',in:'header',required:true,schema:str(100)});
 let output=o.output;if(o.page){output='Page'+o.output;S[output]??=obj({items:arr(ref(o.output),100),nextCursor:nullable(str(4096)),hasMore:{type:'boolean'}});}
 if(o.unsubscribe){const keyIndex=params.findIndex(p=>p.name==='Idempotency-Key');if(keyIndex>=0)params[keyIndex].required=false;}
 const async=o.output==='Job';const code=async?'202':o.method==='post'&&!o.webhook&&!o.public?'201':'200';
 const response={description:async?'Accepted durable operation; poll the job.':o.webhook?'Signature verified and event durably recorded before acknowledgment.':'Successful authorized response.',headers:{'X-Trace-Id':{schema:str(80),description:'Correlation ID; contains no contact data.'},ETag:{schema:str(100),description:'Resource version when relevant.'}},content:{'application/json':{schema:ref(output)}}};
 const responses={[code]:response};for(const e of [400,401,403,404,409,412,422,429,503])responses[e]={description:{400:'Malformed request',401:'Authentication required or expired',403:'Permission, entitlement, policy or signature denied',404:'Unavailable or out-of-scope resource',409:'Business conflict or idempotency-key hash mismatch',412:'Resource revision changed',422:'Schema/business validation failed',429:'Quota exceeded; Retry-After required',503:'Provider unavailable or stale data exceeds policy'}[e],content:{'application/problem+json':{schema:ref('Problem')}}};
 const operation={operationId:o.id,tags:[o.module],summary:o.id.replace(/([A-Z])/g,' $1'),description:'Permission: '+o.permission+'. See module requirements for row scope, validation, entitlement and side-effect rules.',parameters:params,responses,'x-permission':o.permission,'x-tenant-context':o.public||o.visitor?'verified published site and site-bound visitor':o.staff?'staff authorization + scoped control plane':'verified active organization membership','x-rate-limit':o.webhook?'provider-specific signature budget':o.module==='AI'?'20 jobs per member per hour plus organization cost cap':o.public?'site + IP abuse limits; form 10 per 10 minutes':o.method==='get'?'300 requests per member per minute':'120 requests per member per minute; provider side effects also have organization quotas'};
 operation.responses['429'].headers={'Retry-After':{required:true,schema:{type:'integer',minimum:1},description:'Delay in seconds before retry.'}};
 if(o.module==='AI'&&o.method==='get')operation['x-rate-limit']='300 reads/member/minute; polling backoff recommended';
 if(o.analytics){operation['x-rate-limit']='20 events/site/IP/minute and tenant ingestion budget; configurable';operation['x-consent-required']='Approved analytics purpose; no query strings or PII; suppress when consent is absent';}
 if(o.public)operation.security=[];if(o.visitor)operation.security=[{VisitorSession:[]}];if(o.webhook){operation.security=[{StripeSignature:[]},{TwilioSignature:[]},{SvixId:[],SvixTimestamp:[],SvixSignature:[]}];operation['x-provider-payload']='Actual signed raw provider body; provider route chooses exactly its required signature scheme. A signature for a different provider is never accepted.';}
 if(o.input)operation.requestBody={required:true,content:{'application/json':{schema:ref(o.input)}}};
 if(o.unsubscribe){operation['x-tenant-context']='Signed, purpose-bound channel token resolved server-side; no tenant IDs accepted from caller';operation['x-token-required']=true;operation['x-idempotency']='Token hash and withdrawal state make repeated requests safe';}
 if(o.oneClick){operation.parameters=operation.parameters.filter(p=>p.name!=='Idempotency-Key');operation.parameters.push({name:'token',in:'query',required:true,schema:str(4096)});operation.requestBody={required:true,content:{'application/x-www-form-urlencoded':{schema:obj({'List-Unsubscribe':{type:'string',const:'One-Click'}})}}};operation['x-cookie-authentication']=false;operation['x-redirects-allowed']=false;}
 if(o.webhook){operation.requestBody={required:true,description:'Exact raw signed vendor payload; normalized WebhookEnvelope is produced internally after validation.',content:{'application/json':{schema:{type:'object'}},'application/x-www-form-urlencoded':{schema:{type:'object',additionalProperties:{type:'string'}}}}};operation['x-signature-required']=true;operation['x-signature-registry']={stripe:'Stripe-Signature',twilio:'X-Twilio-Signature',resend:'svix-id + svix-timestamp + svix-signature',others:'Provider contract required before enablement'};}
 api.paths[o.url]??={};api.paths[o.url][o.method]=operation;
 }
 delete api.components.securitySchemes.ProviderSignature;
 api.components.securitySchemes.StripeSignature={type:'apiKey',in:'header',name:'Stripe-Signature',description:'Verify exact raw request body, timestamp tolerance and endpoint secret using the official Stripe verifier.'};
 api.components.securitySchemes.TwilioSignature={type:'apiKey',in:'header',name:'X-Twilio-Signature',description:'Verify canonical configured public URL and provider payload with the official Twilio verifier; never trust forwarded host headers.'};
 api.components.securitySchemes.SvixId={type:'apiKey',in:'header',name:'svix-id'};
 api.components.securitySchemes.SvixTimestamp={type:'apiKey',in:'header',name:'svix-timestamp'};
 api.components.securitySchemes.SvixSignature={type:'apiKey',in:'header',name:'svix-signature',description:'All three Svix headers required for Resend; verify exact raw body with the provider verifier.'};
 api.info.title='Independent Real Estate SaaS API — Design Contract';
 return api;
}

export async function buildContracts(){await fs.mkdir(path.join(out,'contracts'),{recursive:true});await fs.mkdir(path.join(out,'data'),{recursive:true});const api=openapi();await fs.writeFile(path.join(out,'contracts/openapi.json'),JSON.stringify(api,null,2));await fs.writeFile(path.join(out,'data/schema.sql'),schemaSql());await fs.writeFile(path.join(out,'data/data-dictionary.json'),JSON.stringify({status:'Proposed design baseline; not applied',tables},null,2));return {tables:tables.length,operations:operations.length,schemas:Object.keys(api.components.schemas).length};}
